1	export type Item = { type: string; cursed?: boolean; enchantment?: number };
2	export type Damage = { itemType: string; amount: number };
3	export type Incident = { cause: string; damages: Damage[] };
4	export type QuoteStep = { op: "quote"; items: Item[] };
5	export type ClaimStep = { op: "claim"; policy: number; incident: Incident };
6	export type Step = QuoteStep | ClaimStep;
7	export type Customer = { yearsWithMHPCO: number };
8	export type Scenario = { customer: Customer; steps: Step[] };
9	export type QuoteResult = { premium: number };
10	export type ClaimResult = { payout: number; remainingCap: number };
11	export type Result = QuoteResult | ClaimResult;
12	export type ScenarioOutcome = { results: Result[] };
13	
14	const BASE_PREMIUMS: Record<string, number> = {
15	  sword: 100,
16	  amulet: 60,
17	  staff: 80,
18	  potion: 40,
19	  rune: 25,
20	  moonstone: 25,
21	};
22	
23	const INSURANCE_VALUES: Record<string, number> = {
24	  sword: 1000,
25	  amulet: 600,
26	  staff: 800,
27	  potion: 400,
28	  rune: 250,
29	  moonstone: 250,
30	};
31	
32	const FIRST_INSURANCE_SURCHARGE = 1.1;
33	const PROCESSING_FEE = 5;
34	
35	// Guards against binary-float artifacts (e.g. 52.800000000000004) tipping an
36	// exact value over a whole-gold boundary and inflating the premium by 1 G.
37	const FLOAT_ARTIFACT_PRECISION = 6;
38	
39	const roundUpToWholeGold = (amount: number): number =>
40	  Math.ceil(Number(amount.toFixed(FLOAT_ARTIFACT_PRECISION)));
41	
42	// Multipliers on the base premium, not amounts added to it.
43	const CURSED_RISK_FACTOR = 1.5;
44	const HIGH_ENCHANTMENT_RISK_FACTOR = 1.3;
45	const NO_ADDED_RISK = 1;
46	
47	const HIGH_ENCHANTMENT_LEVEL = 5;
48	
49	const isHighlyEnchanted = (item: Item): boolean =>
50	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
51	
52	// Risks compound: an item that is both cursed and highly enchanted carries
53	// both factors.
54	const riskFactorOf = (item: Item): number =>
55	  (item.cursed ? CURSED_RISK_FACTOR : NO_ADDED_RISK) *
56	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_RISK_FACTOR : NO_ADDED_RISK);
57	
58	// The price-list value adjusted for the item's own risk — not the bare
59	// BASE_PREMIUMS figure.
60	const riskAdjustedPremiumOf = (item: Item): number =>
61	  BASE_PREMIUMS[item.type] * riskFactorOf(item);
62	
63	const BUILDING_BLOCK_SIZE = 3;
64	const BUILDING_BLOCK_PREMIUM = 60;
65	
66	const areAlike = (items: Item[]): boolean =>
67	  items.every((item) => item.type === items[0].type);
68	
69	const sumOfPremiums = (items: Item[]): number =>
70	  items.reduce((total, item) => total + riskAdjustedPremiumOf(item), 0);
71	
72	// An unalike list forms no blocks at all, however many items it holds.
73	const buildingBlockCountOf = (items: Item[]): number =>
74	  areAlike(items) ? Math.floor(items.length / BUILDING_BLOCK_SIZE) : 0;
75	
76	// Alike items group into building blocks priced below the sum of their members'
77	// individual premiums; everything left over prices individually.
78	const blockPricedTotalOf = (items: Item[]): number => {
79	  const blocks = buildingBlockCountOf(items);
80	  const looseItems = items.slice(blocks * BUILDING_BLOCK_SIZE);
81	
82	  return blocks * BUILDING_BLOCK_PREMIUM + sumOfPremiums(looseItems);
83	};
84	
85	const LOYALTY_DISCOUNT_FACTOR = 0.8;
86	const LOYALTY_YEARS = 2;
87	const NO_DISCOUNT = 1;
88	
89	const isLongStanding = (customer: Customer): boolean =>
90	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
91	
92	const loyaltyFactorOf = (customer: Customer): number =>
93	  isLongStanding(customer) ? LOYALTY_DISCOUNT_FACTOR : NO_DISCOUNT;
94	
95	const REPEAT_CONTRACT_DISCOUNT_FACTOR = 0.85;
96	
97	// The first contract carries the initial assessment surcharge; every contract
98	// after it earns the repeat-contract discount instead.
99	const contractFactorOf = (contractIndex: number): number =>
100	  contractIndex === 0 ? FIRST_INSURANCE_SURCHARGE : REPEAT_CONTRACT_DISCOUNT_FACTOR;
101	
102	// Risk factors attach to a single item; these attach to the policy as a whole,
103	// so they multiply the block-priced total once rather than per item.
104	const policyFactorOf = (customer: Customer, contractIndex: number): number =>
105	  contractFactorOf(contractIndex) * loyaltyFactorOf(customer);
106	
107	// The fee is a flat charge on top of the rounded premium, so it sits outside
108	// the rounding rather than being rounded along with it.
109	const premiumFor = (items: Item[], policyFactor: number): number =>
110	  roundUpToWholeGold(blockPricedTotalOf(items) * policyFactor) + PROCESSING_FEE;
111	
112	const DEDUCTIBLE_PER_INCIDENT = 100;
113	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
114	
115	const insuranceSumOf = (items: Item[]): number =>
116	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
117	
118	const totalReimbursementOf = (incident: Incident, insuredItems: Item[]): number =>
119	  incident.damages.reduce(
120	    (total, damage) => total + reimbursementForDamage(damage, insuredItems),
121	    0,
122	  );
123	
124	// A policy is created by a quote step; claims refer back to it by that step's
125	// index and draw down a shared cap.
126	type Policy = { items: Item[]; cap: number; paidOut: number };
127	
128	const policyFor = (items: Item[]): Policy => ({
129	  items,
130	  cap: insuranceSumOf(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
131	  paidOut: 0,
132	});
133	
134	const FRAGILE_ENCHANTMENT_LEVEL = 8;
135	const FRAGILE_REIMBURSEMENT_RATE = 0.5;
136	const FULL_REIMBURSEMENT_RATE = 1;
137	
138	// Highly enchanted items are volatile, so the MHPCO reimburses only half their
139	// damage. The rate depends on the insured item, which the damage names by type.
140	const reimbursementRateOf = (item: Item): number =>
141	  (item.enchantment ?? 0) >= FRAGILE_ENCHANTMENT_LEVEL
142	    ? FRAGILE_REIMBURSEMENT_RATE
143	    : FULL_REIMBURSEMENT_RATE;
144	
145	const reimbursementForDamage = (damage: Damage, insuredItems: Item[]): number => {
146	  const damagedItem = insuredItems.find((item) => item.type === damage.itemType);
147	
148	  return damage.amount * (damagedItem ? reimbursementRateOf(damagedItem) : 1);
149	};
150	
151	// Settling a claim draws down the policy's cap, so the policy is mutated here
152	// rather than returned alongside the result.
153	const settleClaim = (policy: Policy, incident: Incident): ClaimResult => {
154	  // Damage at or below the deductible pays nothing; it never refunds cap.
155	  const payout = Math.max(
156	    totalReimbursementOf(incident, policy.items) - DEDUCTIBLE_PER_INCIDENT,
157	    0,
158	  );
159	
160	  policy.paidOut += payout;
161	  return { payout, remainingCap: policy.cap - policy.paidOut };
162	};
163	
164	// Only quote steps take out a contract, so the contract number advances
165	// independently of the step number: an intervening claim must not consume one.
166	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
167	  const policies = new Map<number, Policy>();
168	  let contractIndex = 0;
169	
170	  const quote = (step: QuoteStep, stepIndex: number): QuoteResult => {
171	    policies.set(stepIndex, policyFor(step.items));
172	    const premium = premiumFor(
173	      step.items,
174	      policyFactorOf(scenario.customer, contractIndex),
175	    );
176	
177	    contractIndex += 1;
178	    return { premium };
179	  };
180	
181	  const results = scenario.steps.map((step, stepIndex): Result =>
182	    step.op === "claim"
183	      ? settleClaim(policies.get(step.policy)!, step.incident)
184	      : quote(step, stepIndex),
185	  );
186	
187	  return { results };
188	};
